'use strict';
let pushDevice=null,pushTimer=null;try{pushDevice=localStorage.getItem('giorno-push-device');if(!pushDevice){pushDevice=crypto.randomUUID();localStorage.setItem('giorno-push-device',pushDevice);}}catch{}
function pushText(s){$('pushStatus').textContent=s;}
function pushJobs(){const lead=reminderSettings().lead,now=Date.now();
 const blocchi=data.blocks.filter(x=>!x.done).map(b=>({key:b.id+':'+b.date+':'+b.start+':'+lead,title:b.title,due:new Date(new Date(b.date+'T'+b.start+':00').getTime()-lead*60000).toISOString()}));
 const scadenze=(data.family||[]).filter(x=>!x.done&&x.date&&x.notice).map(x=>{const g=new Date(x.date+'T08:30:00');g.setDate(g.getDate()-x.notice);return {key:'fam:'+x.id+':'+x.date+':'+x.notice,title:x.title+' · fra '+(x.notice===1?'un giorno':x.notice+' giorni'),due:g.toISOString()};});
 return [...blocchi,...scadenze].filter(x=>Date.parse(x.due)>now&&Date.parse(x.due)<now+7*86400000).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,250);}
async function syncPush(){if(!cloud||!cloudUser||localStorage.getItem('giorno-push-enabled')!==cloudUser.id)return;try{await cloudRPC('giorno_schedule_push',{p_device:pushDevice,p_jobs:pushJobs()});pushText('Promemoria online aggiornati per i prossimi 7 giorni. Riapri Giorno per mantenerli aggiornati.');}catch{pushText('Non ho aggiornato i promemoria online. Riprova con una connessione attiva; nel frattempo usa il calendario.');}}
$('enablePush').onclick=async()=>{if(!pushDevice||!cloudReady||!cloudConfig.vapidPublicKey){pushText('Le notifiche online richiedono ancora l’attivazione del servizio. Puoi usare Calendario.');return;}if(!cloudUser){pushText('Accedi prima da Famiglia → Famiglia online.');return;}try{if(!('PushManager'in window)||!('serviceWorker'in navigator)||!('Notification'in window))throw Error();const permission=await Notification.requestPermission();if(permission!=='granted'){pushText('Permesso non concesso. Controlla le impostazioni del telefono.');return;}await navigator.serviceWorker.register('./reminders-sw.js');const reg=await navigator.serviceWorker.ready;const raw=cloudConfig.vapidPublicKey.replace(/-/g,'+').replace(/_/g,'/'),key=Uint8Array.from(atob(raw+'='.repeat((4-raw.length%4)%4)),c=>c.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:key});const {error}=await cloud.from('giorno_push_subscriptions').upsert({id:pushDevice,user_id:cloudUser.id,subscription:sub.toJSON()});if(error)throw error;localStorage.setItem('giorno-push-enabled',cloudUser.id);await syncPush();}catch{pushText('Attivazione non riuscita. Su iPhone apri Giorno dalla schermata Home; verifica anche la connessione e i permessi.');}};
$('disablePush').onclick=async()=>{if(!cloudUser||!cloud)return;try{await cloudRPC('giorno_schedule_push',{p_device:pushDevice,p_jobs:[]});const {error}=await cloud.from('giorno_push_subscriptions').delete().eq('id',pushDevice);if(error)throw error;localStorage.removeItem('giorno-push-enabled');const reg=await navigator.serviceWorker.getRegistration();const sub=await reg?.pushManager.getSubscription();await sub?.unsubscribe();pushText('Notifiche online disattivate su questo dispositivo.');}catch{pushText('Non riesco a disattivare il servizio online. Riprova con una connessione attiva.');}};
window.queuePushSync=()=>{clearTimeout(pushTimer);pushTimer=setTimeout(syncPush,1000);};
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')syncPush();});

window.stopPushOnLogout=async()=>{try{if(cloud&&cloudUser){await cloudRPC('giorno_schedule_push',{p_device:pushDevice,p_jobs:[]});await cloud.from('giorno_push_subscriptions').delete().eq('id',pushDevice);}}finally{localStorage.removeItem('giorno-push-enabled');if('serviceWorker'in navigator){const reg=await navigator.serviceWorker.getRegistration();const sub=await reg?.pushManager.getSubscription();await sub?.unsubscribe();}}};
